<?php declare(strict_types=1); require_once __DIR__.'/includes/bootstrap.php'; require_once __DIR__.'/includes/catalog.php';$slug=trim((string)($_GET['slug']??''));$id=(int)($_GET['id']??0);$lesson=$slug?lh_lesson($db,$slug):null;if(!$lesson&&$id>0){try{$q=$db->prepare("SELECT l.slug FROM learning_lessons l WHERE l.id=? LIMIT 1");$q->execute([$id]);$s=(string)$q->fetchColumn();if($s)$lesson=lh_lesson($db,$s);}catch(Throwable){}}if(!$lesson){http_response_code(404);exit('Lesson not found.');}$course=lh_course($db,(string)$lesson['course_slug']);$nav=lh_lesson_nav($db,(int)$course['id'],(int)$lesson['id']);$user=lh_user();$done=false;if($user){try{$q=$db->prepare('SELECT completed FROM learning_progress WHERE user_id=? AND lesson_id=? LIMIT 1');$q->execute([(int)$user['id'],(int)$lesson['id']]);$done=(bool)$q->fetchColumn();}catch(Throwable){}}if($_SERVER['REQUEST_METHOD']==='POST'&&$user){try{$q=$db->prepare('INSERT INTO learning_progress(user_id,lesson_id,completed,progress_percent) VALUES(?,?,1,100) ON DUPLICATE KEY UPDATE completed=1,progress_percent=100');$q->execute([(int)$user['id'],(int)$lesson['id']);$done=true;}catch(Throwable){}}$lh_page_title=$lesson['title'];$lh_description='Learn '.$lesson['title'].' in the SmartToolz Learning Hub.';include __DIR__.'/includes/header.php';include __DIR__.'/includes/navbar.php';?><link rel="stylesheet" href="/learning-hub/assets/css/lesson.css"><div class="container-fluid"><div class="row"><div class="col-lg-3 col-xl-2 p-0"><?php include __DIR__.'/includes/sidebar.php';?></div><main class="col-lg-9 col-xl-10 py-4"><div class="container-fluid"><div class="lh-lesson-layout"><div><?php $lesson_list=$nav['all'];include __DIR__.'/components/lesson-nav.php';?></div><section class="lh-lesson-main"><div class="d-flex justify-content-between small mb-3"><a href="/learning-hub/course.php?slug=<?=rawurlencode($course['slug'])?>" class="text-primary text-decoration-none" data-spa>← <?=lh_h($course['title'])?></a><span class="text-secondary">Lesson <?=number_format((int)$nav['position'])?> / <?=number_format(count($nav['all']))?></span></div><div class="progress lh-progress mb-4"><div class="progress-bar" style="width:<?=count($nav['all'])?round(((int)$nav['position']/count($nav['all']))*100):0?>%"></div></div><article class="lh-card p-4 p-md-5"><span class="badge text-bg-primary mb-3"><?=lh_h($lesson['category_name']??'Learning Hub')?></span><h1 class="display-6 fw-bold"><?=lh_h($lesson['title'])?></h1><div class="lh-prose mt-4"><?= !empty($lesson['content']) ? $lesson['content'] : '<p class="text-secondary">Lesson content is being prepared.</p>' ?></div><?php if($user):?><form method="post" class="mt-4"><button class="btn <?= $done?'btn-success':'btn-primary'?>" type="submit"><?= $done?'✓ Lesson completed':'Mark lesson complete'?></button></form><?php else:?><div class="alert alert-light border mt-4">Login to save your learning progress.</div><?php endif;?></article><div class="lh-next mt-4 p-3 d-flex justify-content-between gap-2"><a class="btn btn-outline-primary <?=empty($nav['previous'])?'disabled':''?>" href="<?=empty($nav['previous'])?'#':'/learning-hub/lesson.php?slug='.rawurlencode($nav['previous']['slug'])?>" data-spa>← Previous</a><a class="btn btn-primary <?=empty($nav['next'])?'disabled':''?>" href="<?=empty($nav['next'])?'#':'/learning-hub/lesson.php?slug='.rawurlencode($nav['next']['slug'])?>" data-spa><?=empty($nav['next'])?'Course Complete':'Next Lesson →'?></a></div><div class="lh-ad-slot my-4">Advertisement</div></section></div></div></main></div></div><?php include __DIR__.'/includes/footer.php';?><script src="/learning-hub/assets/js/app.js"></script><script src="/learning-hub/assets/js/router.js"></script>